import json, hashlib, struct, os
from pathlib import Path
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
base=Path('store/jobs/j000200/out')
seed=(base/'seed.seco').read_bytes(); storage=(base/'storage.seco').read_bytes()
raw=json.loads(Path('store/jobs/j000019/out/uri_passwords.json').read_text())
candidates=raw if isinstance(raw,list) else [raw]
def check(data,pw,keep_plain=False):
    if len(data)<516 or data[:4]!=b'SECO': return {'header':False}
    csum=hashlib.sha256(data[256:512]+data[512:516]+data[516:]).digest()==data[224:256]
    n,r,p=struct.unpack('>III',data[288:300])
    try:
        dkey=hashlib.scrypt(pw,salt=data[256:288],n=n,r=r,p=p,dklen=32)
        key=AESGCM(dkey).decrypt(data[332:344],data[360:392]+data[344:360],None)
    except Exception:
        return {'header':True,'checksum':csum,'key_auth':False,'payload_auth':False}
    try:
        plain=AESGCM(key).decrypt(data[392:404],data[516:]+data[404:420],None)
        result={'header':True,'checksum':csum,'key_auth':len(key)==32,'payload_auth':True,'plaintext_bytes':len(plain)}
        if keep_plain:
            result['plain']=plain
        return result
    except Exception:
        return {'header':True,'checksum':csum,'key_auth':len(key)==32,'payload_auth':False}
seed_auth=[]; storage_auth=[]; skips=0; storage_kinds=[]
for i,item in enumerate(candidates):
    hx=item.get('password_utf8_hex') if isinstance(item,dict) else None
    if not isinstance(hx,str): skips+=1; continue
    try: pw=bytes.fromhex(hx)
    except Exception: skips+=1; continue
    s=check(seed,pw)
    if s.get('key_auth') and s.get('payload_auth'): seed_auth.append(i)
    w=check(storage,pw,keep_plain=True)
    if w.get('key_auth') and w.get('payload_auth'):
        storage_auth.append(i)
        b=w['plain']
        storage_kinds.append('sqlite' if b.startswith(b'SQLite format 3\x00') else ('json' if b.lstrip().startswith((b'{',b'[')) else ('gzip' if b.startswith(b'\x1f\x8b') else ('zlib' if b[:2] in (b'\x78\x01',b'\x78\x9c',b'\x78\xda') else 'unrecognized'))))
        del w['plain']
summary={'candidate_count':len(candidates),'candidate_records_skipped':skips,'seed_authenticated_indices':seed_auth,'storage_authenticated_indices':storage_auth,'storage_plaintext_kinds':storage_kinds,'seed_valid_seco_checksum':hashlib.sha256(seed[256:512]+seed[512:516]+seed[516:]).digest()==seed[224:256],'storage_valid_seco_checksum':hashlib.sha256(storage[256:512]+storage[512:516]+storage[516:]).digest()==storage[224:256]}
Path(os.environ['OUT'],'storage-auth-summary.json').write_text(json.dumps(summary,sort_keys=True,indent=2))
print(json.dumps(summary,sort_keys=True))
